contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 drugs) public payable {
        require(drugs > 0);

        bool reverted;
        c.seedMarket(drugs); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(!reverted && c.initialized() && c.marketDrugs() == drugs);
    }
}

